          example: 'import http from \'http\';\n\n// Graceful shutdown manager\nclass GracefulShutdown {\n  constructor(server, options = {}) {\n    this.server = server;\n    this.timeout = options.timeout || 30000; // 30 seconds\n    this.cleanupTasks = [];\n    this.isShuttingDown = false;\n  }\n  \n  addCleanupTask(task) {\n    this.cleanupTasks.push(task);\n  }\n  \n  async shutdown() {\n    if (this.isShuttingDown) {\n      console.log(\'Shutdown already in progress\');\n      return;\n    }\n    \n    this.isShuttingDown = true;\n    console.log(\'Starting graceful shutdown...\');\n    \n    // Stop accepting new connections\n    this.server.close(() => {\n      console.log(\'HTTP server closed\');\n    });\n    \n    // Run cleanup tasks with timeout\n    const cleanupPromise = Promise.all(\n      this.cleanupTasks.map(async (task) => {\n        try {\n          await task();\n        } catch (error) {\n          console.error(\'Cleanup task failed:\', error);\n        }\n      })\n    );\n    \n    // Wait for cleanup or timeout\n    try {\n      await Promise.race([\n        cleanupPromise,\n        new Promise((_, reject) => \n          setTimeout(() => reject(new Error(\'Shutdown timeout\')), this.timeout)\n        )\n      ]);\n      console.log(\'Graceful shutdown completed\');\n    } catch (error) {\n      console.error(\'Shutdown error:\', error);\n      process.exit(1);\n    }\n    \n    process.exit(0);\n  }\n}\n\n// Usage\nconst server = http.createServer(app);\nconst shutdownManager = new GracefulShutdown(server);\n\n// Add cleanup tasks\nshutdownManager.addCleanupTask(async () => {\n  console.log(\'Closing database connections...\');\n  await database.close();\n});\n\nshutdownManager.addCleanupTask(async () => {\n  console.log(\'Closing Redis connections...\');\n  await redis.quit();\n});\n\n// Handle shutdown signals\nprocess.on(\'SIGTERM\', () => {\n  console.log(\'Received SIGTERM\');\n  shutdownManager.shutdown();\n});\n\nprocess.on(\'SIGINT\', () => {\n  console.log(\'Received SIGINT\');\n  shutdownManager.shutdown();\n});\n\nprocess.on(\'SIGUSR2\', () => {\n  console.log(\'Received SIGUSR2 (nodemon restart)\');\n  shutdownManager.shutdown();\n});',
