          example: '// Global error handlers\nprocess.on(\'uncaughtException\', (error) => {\n  console.error(\'Uncaught Exception:\', error);\n  // Log error to external service\n  logErrorToService(error);\n  // Graceful shutdown\n  process.exit(1);\n});\n\nprocess.on(\'unhandledRejection\', (reason, promise) => {\n  console.error(\'Unhandled Rejection at:\', promise, \'reason:\', reason);\n  // Log error to external service\n  logErrorToService(new Error(reason));\n});\n\n// Error reporting service\nasync function logErrorToService(error) {\n  try {\n    await fetch(\'https://error-reporting-service.com/api/errors\', {\n      method: \'POST\',\n      headers: { \'Content-Type\': \'application/json\' },\n      body: JSON.stringify({\n        message: error.message,\n        stack: error.stack,\n        timestamp: new Date().toISOString(),\n        environment: process.env.NODE_ENV,\n        version: process.env.APP_VERSION\n      })\n    });\n  } catch (reportingError) {\n    console.error(\'Failed to report error:\', reportingError);\n  }\n}\n\n// Custom error class\nclass AppError extends Error {\n  constructor(message, statusCode, isOperational = true) {\n    super(message);\n    this.statusCode = statusCode;\n    this.isOperational = isOperational;\n    \n    Error.captureStackTrace(this, this.constructor);\n  }\n}\n\n// Error handling middleware\nconst errorHandler = (error, req, res, next) => {\n  let err = { ...error };\n  err.message = error.message;\n\n  // Log error\n  console.error(error);\n\n  // Mongoose bad ObjectId\n  if (error.name === \'CastError\') {\n    const message = \'Resource not found\';\n    err = new AppError(message, 404);\n  }\n\n  // Mongoose duplicate key\n  if (error.code === 11000) {\n    const message = \'Duplicate field value\';\n    err = new AppError(message, 400);\n  }\n\n  // Mongoose validation error\n  if (error.name === \'ValidationError\') {\n    const message = Object.values(error.errors).map(val => val.message);\n    err = new AppError(message, 400);\n  }\n\n  res.status(err.statusCode || 500).json({\n    success: false,\n    error: err.message || \'Server Error\'\n  });\n};\n\n// Async error wrapper\nconst catchAsync = (fn) => {\n  return (req, res, next) => {\n    fn(req, res, next).catch(next);\n  };\n};\n\n// Usage\napp.get(\'/users\', catchAsync(async (req, res, next) => {\n  const users = await User.find();\n  res.status(200).json({ success: true, data: users });\n}));',
